<?= $this->include('layouts/header') ?><div class="page-head"><div><div class="page-kicker">Report</div><h1 class="page-title"><?=esc($title)?></h1><p class="page-subtitle">Filter and export confirmed or voided movement records.</p></div><div class="head-actions"><a class="btn" href="<?=site_url('reports')?>">← Reports</a><a class="btn primary" href="<?=site_url('reports/export/'.$type)?>">Export CSV</a></div></div><div class="card"><form class="toolbar" method="get"><div class="filters" style="width:100%"><input type="date" name="from" value="<?=esc($from)?>"><input type="date" name="to" value="<?=esc($to)?>"><input name="product" placeholder="Product or code" value="<?=esc($product)?>"><input name="party_name" placeholder="Supplier / destination" value="<?=esc($party_name)?>"><button class="btn primary small" type="submit">Apply filters</button></div></form><div class="table-wrap"><table class="table"><thead><tr><th>Transaction</th><th>Date/time</th><th>Reference</th><th>Party</th><th>Vehicle</th><th>User</th><th>Items</th><th>Status</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="8"><div class="empty"><strong>No movements found</strong>Adjust the filters or date range.</div></td></tr><?php else: foreach($rows as $r): ?><tr><td class="mono"><?=esc($r['transaction_no'])?></td><td><?=esc($r['created_at'])?></td><td><?=esc($r['reference_no']??'—')?></td><td><?=esc($r['party_name']??'—')?></td><td><?=esc($r['vehicle_no']??'—')?></td><td><?=esc($r['user_name'])?></td><td><?=esc($r['items'])?></td><td><span class="badge <?=$r['status']==='VOID'?'neutral':'success'?>"><?=esc($r['status'])?></span></td></tr><?php endforeach; endif; ?></tbody></table></div></div><?= $this->include('layouts/footer') ?>